function Icon({ name, size = 16, color }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none"
      stroke={color || 'currentColor'} strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round">
      {ICON_PATHS[name]}
    </svg>
  );
}

/* ---- Status helpers ---- */
function StatusChip({ status }) {
  const map = {
    pending:   { label: '승인 대기', cls: 'chip-warn' },
    approved:  { label: '승인됨', cls: 'chip-info' },
    shipped:   { label: '배송 중', cls: 'chip-ok' },
    delivered: { label: '수령 완료', cls: 'chip-neutral' },
    rejected:  { label: '반려됨', cls: 'chip-err' },
  };
  const s = map[status] || { label: status, cls: 'chip-neutral' };
  return <span className={`chip ${s.cls}`}><span className="dot"></span>{s.label}</span>;
}

function fmtPts(n) { return n.toLocaleString('ko-KR'); }

/* ---- Sidebar ---- */
function Sidebar({ role, setRole, screen, setScreen, openCart, cartQty, onLogout }) {
  const store = useStore();
  const pendingOrderCount = store.orders.filter(o => o.status === 'pending').length;

  const empNav = [
    { id:'home',    label:'홈',        icon:'home' },
    { id:'catalog', label:'카탈로그',   icon:'catalog' },
    { id:'cart',    label:'장바구니',   icon:'cart', dynamicBadge: cartQty > 0 ? String(cartQty) : null },
    { id:'orders',  label:'주문 내역',  icon:'orders' },
  ];
  const adminNav = [
    { id:'admin-dashboard',  label:'대시보드',   icon:'gauge' },
    { id:'admin-orders',     label:'주문 승인',   icon:'approve', dynamicBadge: pendingOrderCount > 0 ? String(pendingOrderCount) : null },
    { id:'admin-points',     label:'포인트 지급', icon:'points' },
    { id:'admin-inventory',  label:'재고 관리',   icon:'inventory' },
    { type:'section', label:'관리 시스템' },
    { id:'admin-products',   label:'상품 관리',   icon:'catalog' },
    { id:'admin-banners',    label:'배너 관리',   icon:'banner' },
    { id:'admin-order-mgmt', label:'주문 관리',   icon:'truck' },
    { id:'admin-employees',  label:'직원 관리',   icon:'users' },
  ];
  const nav = role === 'employee' ? empNav : adminNav;

  return (
    <aside className="sidebar">
      <div className="sb-top">
        <div className="sb-logo">
          <img src="data:image/png;base64," alt="WindTree" style={{height:28, width:"auto"}}/>
        </div>
        {role === 'admin' && (
          <div className="sb-role">
            <button className={role==='employee'?'active':''} onClick={()=>{setRole('employee');setScreen('home');}}>직원</button>
            <button className={role==='admin'?'active':''} onClick={()=>{setRole('admin');setScreen('admin-dashboard');}}>관리자</button>
          </div>
        )}
      </div>
      <nav className="sb-nav">
        {nav.map((item, i) => {
          const badge = item.dynamicBadge;
          return item.type === 'section'
            ? <div key={i} className="sb-section">{item.label}</div>
            : (
              <button key={item.id} className={`sb-item${screen===item.id&&item.id!=='cart'?' active':''}`}
                onClick={()=>(item.id==='cart'&&role==='employee')?openCart?.():setScreen(item.id)}>
                <Icon name={item.icon}/>
                <span>{item.label}</span>
                {badge && screen!==item.id && <span className="badge">{badge}</span>}
              </button>
            );
        })}
      </nav>
      <div className="sb-user">
        <div className="sb-avatar">{EMPLOYEE.avatar}</div>
        <div className="sb-user-info">
          <div className="name">{EMPLOYEE.name}</div>
          <div className="role-label">{role === 'employee' ? EMPLOYEE.dept : '관리자'}</div>
        </div>
      </div>
      <button
        onClick={onLogout}
        style={{
          margin: '0 12px 12px',
          padding: '9px 16px',
          width: 'calc(100% - 24px)',
          border: '1px solid var(--border-hairline)',
          borderRadius: 'var(--radius-sm)',
          background: 'transparent',
          color: 'var(--fg-3)',
          fontSize: 13,
          fontWeight: 500,
          cursor: 'pointer',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          gap: 6,
          transition: 'background var(--dur-fast)',
        }}
        onMouseEnter={e => e.currentTarget.style.background = 'var(--accent-050)'}
        onMouseLeave={e => e.currentTarget.style.background = 'transparent'}
      >
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
          <path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/>
          <polyline points="16 17 21 12 16 7"/>
          <line x1="21" y1="12" x2="9" y2="12"/>
        </svg>
        로그아웃
      </button>
    </aside>
  );
}

Object.assign(window, { Icon, StatusChip, fmtPts, Sidebar, useStore, PRODUCTS, ORDERS, EMPLOYEES, EMPLOYEE, WW, WW_CONFIG });
